// DocumentsHandler is an implementation of the elephant.repository.Documents service.
type DocumentsHandler interface {
	// Get retrieves a document version.
	Get(context.Context, *connect.Request[repository.GetDocumentRequest]) (*connect.Response[repository.GetDocumentResponse], error)
	// BulkGet loads multiple documents in a single request.
	BulkGet(context.Context, *connect.Request[repository.BulkGetRequest]) (*connect.Response[repository.BulkGetResponse], error)
	// GetHistory lists the document version history.
	GetHistory(context.Context, *connect.Request[repository.GetHistoryRequest]) (*connect.Response[repository.GetHistoryResponse], error)
	// Update is used to create new document versions, set statuses, update ACLs.
	Update(context.Context, *connect.Request[repository.UpdateRequest]) (*connect.Response[repository.UpdateResponse], error)
	// BulkUpdate is used to create new document versions, set statuses, update ACLs.
	BulkUpdate(context.Context, *connect.Request[repository.BulkUpdateRequest]) (*connect.Response[repository.BulkUpdateResponse], error)
	// Validate is used to validate a document without writing it to the
	// repository.
	Validate(context.Context, *connect.Request[repository.ValidateRequest]) (*connect.Response[repository.ValidateResponse], error)
	// Prune will attempt to remove invalid parts of a document until what remains
	// is valid. If that's not possible it will return the same kind of error
	// information as a Validate call would return, highlighting the remaining
	// issues.
	Prune(context.Context, *connect.Request[repository.PruneRequest]) (*connect.Response[repository.PruneResponse], error)
	// Evict removes stored document versions from the main database. The evicted
	// data will be restored from the archive if requested again by clients. It's
	// not allowed to evict the current version of a document.
	Evict(context.Context, *connect.Request[repository.EvictRequest]) (*connect.Response[repository.EvictResponse], error)
	// Delete deletes a document and all its associated data.
	Delete(context.Context, *connect.Request[repository.DeleteDocumentRequest]) (*connect.Response[repository.DeleteDocumentResponse], error)
	// ListDeleted lists deleted document instances for a UUID.
	ListDeleted(context.Context, *connect.Request[repository.ListDeletedRequest]) (*connect.Response[repository.ListDeletedResponse], error)
	// Restore recovers a deleted document.
	Restore(context.Context, *connect.Request[repository.RestoreRequest]) (*connect.Response[repository.RestoreResponse], error)
	// Purge removes a deleted document completely.
	Purge(context.Context, *connect.Request[repository.PurgeRequest]) (*connect.Response[repository.PurgeResponse], error)
	// GetMeta returns metadata for a document, including the ACL and current
	// status heads.
	GetMeta(context.Context, *connect.Request[repository.GetMetaRequest]) (*connect.Response[repository.GetMetaResponse], error)
	// Eventlog returns document update events, optionally waiting for new events.
	Eventlog(context.Context, *connect.Request[repository.GetEventlogRequest]) (*connect.Response[repository.GetEventlogResponse], error)
	// CompactedEventlog returns document update events. If more than one event
	// has occured for a document in the given window only the latest will be returned.
	CompactedEventlog(context.Context, *connect.Request[repository.GetCompactedEventlogRequest]) (*connect.Response[repository.GetCompactedEventlogResponse], error)
	// GetStatus returns a single status for a document.
	GetStatus(context.Context, *connect.Request[repository.GetStatusRequest]) (*connect.Response[repository.GetStatusResponse], error)
	// GetStatusHistory returns the history of a status for a document.
	GetStatusHistory(context.Context, *connect.Request[repository.GetStatusHistoryRequest]) (*connect.Response[repository.GetStatusHistoryReponse], error)
	// GetNilStatuses returns all the statuses for a document where version is -1.
	GetNilStatuses(context.Context, *connect.Request[repository.GetNilStatusesRequest]) (*connect.Response[repository.GetNilStatusesResponse], error)
	// GetStatusOverview returns the current version and a set of statuses for a
	// gven list of documents.
	GetStatusOverview(context.Context, *connect.Request[repository.GetStatusOverviewRequest]) (*connect.Response[repository.GetStatusOverviewResponse], error)
	// GetPermissions returns the permissions you have for the document.
	GetPermissions(context.Context, *connect.Request[repository.GetPermissionsRequest]) (*connect.Response[repository.GetPermissionsResponse], error)
	// Lock attempts to acquire a write lock on a document. Fails with
	// FailedPrecondition when the document is already locked; the
	// failure carries error metadata keys "lock_holder_sub",
	// "lock_app", "lock_comment" and "lock_expires" so callers can
	// distinguish "held by me" (look up the token in own state) from
	// "held by someone else" (surface to the user).
	Lock(context.Context, *connect.Request[repository.LockRequest]) (*connect.Response[repository.LockResponse], error)
	// ExtendLock extends the expiration of an existing lock.
	ExtendLock(context.Context, *connect.Request[repository.ExtendLockRequest]) (*connect.Response[repository.LockResponse], error)
	// Unlock releases a write lock on a document.
	Unlock(context.Context, *connect.Request[repository.UnlockRequest]) (*connect.Response[repository.UnlockResponse], error)
	// GetWithheld returns the next upcoming scheduled publish actions. This is
	// not a complete list, but a list of the next N documents that are considered
	// eligible for publishing.
	GetWithheld(context.Context, *connect.Request[repository.GetWithheldRequest]) (*connect.Response[repository.GetWithheldResponse], error)
	// GetDeliverableInfo returns available information related to the deliverable.
	GetDeliverableInfo(context.Context, *connect.Request[repository.GetDeliverableInfoRequest]) (*connect.Response[repository.GetDeliverableInfoResponse], error)
	// BulkGetDeliverableInfo returns deliverable information for multiple
	// documents in a single request.
	BulkGetDeliverableInfo(context.Context, *connect.Request[repository.BulkGetDeliverableInfoRequest]) (*connect.Response[repository.BulkGetDeliverableInfoResponse], error)
	// CreateUpload is used to start the process of uploading objects that then
	// can be attached to a document.
	CreateUpload(context.Context, *connect.Request[repository.CreateUploadRequest]) (*connect.Response[repository.CreateUploadResponse], error)
	// GetAttachments returns download links for the requested attachments.
	GetAttachments(context.Context, *connect.Request[repository.GetAttachmentsRequest]) (*connect.Response[repository.GetAttachmentsResponse], error)
	// GetMatching returns documents matching the given criteria.
	GetMatching(context.Context, *connect.Request[repository.GetMatchingRequest]) (*connect.Response[repository.GetMatchingResponse], error)
	// GetSocketToken returns a token that can be used to open socket connections.
	GetSocketToken(context.Context, *connect.Request[repository.GetSocketTokenRequest]) (*connect.Response[repository.GetSocketTokenResponse], error)
}

